//! The three synthetic example tables shipped with the lessons (generated by
//! `examples/generate.py`; see its docstring for the mechanisms).

pub const NAMES: [&str; 3] = ["Income, age and year", "Diamond prices", "Florida communities"];

/// CSV text of a bundled example by its display name.
pub fn csv(name: &str) -> Option<&'static str> {
    match name {
        "Income, age and year" => Some(include_str!("../../../examples/income.csv")),
        "Diamond prices" => Some(include_str!("../../../examples/diamonds.csv")),
        "Florida communities" => Some(include_str!("../../../examples/florida.csv")),
        _ => None,
    }
}

#[cfg(test)]
mod tests {
    #[test]
    fn every_named_example_is_bundled() {
        for n in super::NAMES {
            assert!(super::csv(n).is_some_and(|t| t.lines().count() > 10), "{n}");
        }
        assert!(super::csv("nope").is_none());
    }
}
